mapper.select:
SELECT *
FROM doctor_merchant_appointment AS dma
INNER JOIN hospital AS hos ON dma.hospital_id = hos.id
WHERE
    hos.province = #{location.province} 

        AND hos.city = #{location.city}


        AND hos.region = #{location.region}

    AND dma.department_id = #{departmentCode}

        AND dma.subject_id = #{SubjectCode}


        AND (DATE(dma.begin_date) = DATE(#{date}) OR   
        DATE(dma.end_date) = DATE(#{date}) OR          
        (dma.begin_date <= #{date} AND dma.end_date >= #{date}))
